index 000000000..89248261d
--- /dev/null
+++ b/apps/fabro-web/app/components/key-value-editor.test.tsx
@@ -0,0 +1,81 @@
+import { afterEach, beforeEach, describe, expect, test } from "bun:test";
+import { useState } from "react";
+import TestRenderer, { act } from "react-test-renderer";
+
+import { setupReactTestEnv } from "../lib/test-utils";
+import { KeyValueEditor, entriesFromMap, mapFromEntries } from "./key-value-editor";
+
+let teardownReactTestEnv: (() => void) | undefined;
+const mountedRenderers: TestRenderer.ReactTestRenderer[] = [];
+
+describe("key/value helpers", () => {
+  test("mapFromEntries trims keys and drops blank keys", () => {
+    expect(
+      mapFromEntries([
+        { key: " FOO ", value: "bar" },
+        { key: "   ", value: "ignored" },
+        { key: "BAZ", value: "qux" },
+      ]),
+    ).toEqual({ FOO: "bar", BAZ: "qux" });
+  });
+
+  test("entriesFromMap round-trips through mapFromEntries", () => {
+    const map = { FOO: "bar", BAZ: "qux" };
+    expect(mapFromEntries(entriesFromMap(map)))
+      .toEqual(map);
+  });
+});
+
+describe("KeyValueEditor", () => {
+  beforeEach(() => {
+    teardownReactTestEnv = setupReactTestEnv();
+  });
+
+  afterEach(() => {
+    act(() => {
+      for (const renderer of mountedRenderers.splice(0)) {
+        renderer.unmount();
+      }
+    });
+    teardownReactTestEnv?.();
+    teardownReactTestEnv = undefined;
+  });
+
+  test("adds and removes rows", () => {
+    let renderer: TestRenderer.ReactTestRenderer | undefined;
+
+    function Host() {
+      const [entries, setEntries] = useState([{ key: "FOO", value: "bar" }]);
+      return (
+        <KeyValueEditor
+          entries={entries}
+          onChange={setEntries}
+          keyPlaceholder="KEY"
+          valuePlaceholder="VALUE"
+          addLabel="Add row"
+        />
+      );
+    }
+
+    act(() => {
+      renderer = TestRenderer.create(<Host />);
+    });
+    mountedRenderers.push(renderer!);
+    expect(renderer!.root.findAllByProps({ "aria-label": "Key" })).toHaveLength(1);
+
+    const addButton = renderer!.root
+      .findAllByType("button")
+      .find((button) => button.props["aria-label"] === undefined);
+    expect(addButton).toBeDefined();
+    act(() => {
+      addButton!.props.onClick();
+    });
+    expect(renderer!.root.findAllByProps({ "aria-label": "Key" })).toHaveLength(2);
+
+    const removeButtons = renderer!.root.findAllByProps({ "aria-label": "Remove row" });
+    act(() => {
+      removeButtons[0].props.onClick();
+    });
+    expect(renderer!.root.findAllByProps({ "aria-label": "Key" })).toHaveLength(1);
+  });
+});
diff --git a/apps/fabro-web/app/components/key-value-editor.tsx b/apps/fabro-web/app/components/key-value-editor.tsx
new file mode 100644
index 000000000..fb4014d6d
--- /dev/null
+++ b/apps/fabro-web/app/components/key-value-editor.tsx
@@ -0,0 +1,102 @@
+import type { ReactNode } from "react";
+import { PlusIcon, XMarkIcon } from "@heroicons/react/16/solid";
+
+import { INPUT_CLASS } from "./ui";
+
+export interface KeyValueEntry {
+  key: string;
+  value: string;
+}
+
+export function entriesFromMap(map: { [key: string]: string }): KeyValueEntry[] {
+  return Object.entries(map).map(([key, value]) => ({ key, value }));
+}
+
+export function mapFromEntries(entries: KeyValueEntry[]): { [key: string]: string } {
+  return Object.fromEntries(
+    entries
+      .map((entry): [string, string] => [entry.key.trim(), entry.value])
+      .filter((entry) => entry[0] !== ""),
+  );
+}
+
+export function KeyValueEditor({
+  entries,
+  onChange,
+  keyPlaceholder,
+  valuePlaceholder,
+  addLabel,
+  renderEntryHint,
+}: {
+  entries: KeyValueEntry[];
+  onChange: (entries: KeyValueEntry[]) => void;
+  keyPlaceholder: string;
+  valuePlaceholder: string;
+  addLabel: string;
+  renderEntryHint?: (entry: KeyValueEntry, index: number) => ReactNode;
+}) {
+  function update(index: number, partial: Partial<KeyValueEntry>) {
+    onChange(entries.map((entry, i) => (i === index ? { ...entry, ...partial } : entry)));
+  }
+
+  return (
+    <div className="space-y-2">
+      {entries.map((entry, index) => (
+        <div key={index} className="space-y-1">
+          <div className="flex items-center gap-2">
+            <input
+              type="text"
+              aria-label="Key"
+              value={entry.key}
+              onChange={(e) => update(index, { key: e.target.value })}
+              placeholder={keyPlaceholder}
+              autoComplete="off"
+              spellCheck={false}
+              className={`${INPUT_CLASS} font-mono`}
+            />
+            <input
+              type="text"
+              aria-label="Value"
+              value={entry.value}
+              onChange={(e) => update(index, { value: e.target.value })}
+              placeholder={valuePlaceholder}
+              autoComplete="off"
+              spellCheck={false}
+              className={`${INPUT_CLASS} font-mono`}
+            />
+            <RemoveButton onClick={() => onChange(entries.filter((_, i) => i !== index))} />
+          </div>
+          {renderEntryHint ? renderEntryHint(entry, index) : null}
+        </div>
+      ))}
+      <AddButton label={addLabel} onClick={() => onChange([...entries, { key: "", value: "" }])} />
+    </div>
+  );
+}
+
+function AddButton({ label, onClick }: { label: string; onClick: () => void }) {
+  return (
+    <button
+      type="button"
+      onClick={onClick}
+      className="inline-flex items-center gap-1.5 rounded-md border border-line bg-panel/80 px-2.5 py-1 text-xs font-medium text-fg-3 transition-colors hover:border-line-strong hover:bg-panel hover:text-fg"
+    >
+      <PlusIcon className="size-3.5" aria-hidden="true" />
+      {label}
+    </button>
+  );
+}
+
+function RemoveButton({ onClick }: { onClick: () => void }) {
+  return (
+    <button
+      type="button"
+      onClick={onClick}
+      aria-label="Remove row"
+      title="Remove"
+      className="flex size-9 shrink-0 items-center justify-center rounded-lg text-fg-muted transition-colors hover:bg-overlay hover:text-coral"
+    >
+      <XMarkIcon className="size-4" aria-hidden="true" />
+    </button>
+  );
+}
