diff --git a/apps/fabro-web/app/lib/credential-heuristics.test.ts b/apps/fabro-web/app/lib/credential-heuristics.test.ts
new file mode 100644
index 000000000..3f571c0f8
--- /dev/null
+++ b/apps/fabro-web/app/lib/credential-heuristics.test.ts
@@ -0,0 +1,57 @@
+import { describe, expect, test } from "bun:test";
+
+import {
+  looksLikeCredential,
+  secretNameForKey,
+  secretReference,
+} from "./credential-heuristics";
+
+describe("credential heuristics", () => {
+  test("flags Authorization bearer values", () => {
+    expect(looksLikeCredential("Authorization", "Bearer abc123"))
+      .toBe(true);
+  });
+
+  test("flags API key names", () => {
+    expect(looksLikeCredential("API_KEY", "abc"))
+      .toBe(true);
+    expect(looksLikeCredential("x-api-key", "abc"))
+      .toBe(true);
+  });
+
+  test("does not flag ordinary environment values", () => {
+    expect(looksLikeCredential("NODE_ENV", "production"))
+      .toBe(false);
+  });
+
+  test("does not flag already templated references", () => {
+    expect(looksLikeCredential("API_KEY", "{{ secrets.OPENAI_API_KEY }}"))
+      .toBe(false);
+    expect(looksLikeCredential("TOKEN", "{{ env.GITHUB_TOKEN }}"))
+      .toBe(false);
+    expect(looksLikeCredential("PASSWORD", "{{ vars.RUNTIME_PASSWORD }}"))
+      .toBe(false);
+  });
+
+  test("does not flag empty values", () => {
+    expect(looksLikeCredential("PASSWORD", ""))
+      .toBe(false);
+  });
+
+  test("flags long high-entropy-looking values under benign keys", () => {
+    expect(looksLikeCredential("session_id", "aBcdEf1234567890Ghij"))
+      .toBe(true);
+  });
+
+  test("derives secret names from keys", () => {
+    expect(secretNameForKey("x-api-key"))
+      .toBe("X_API_KEY");
+    expect(secretNameForKey("  "))
+      .toBe("SECRET");
+  });
+
+  test("builds secret interpolation references", () => {
+    expect(secretReference("X_API_KEY"))
+      .toBe("{{ secrets.X_API_KEY }}");
+  });
+});
diff --git a/apps/fabro-web/app/lib/credential-heuristics.ts b/apps/fabro-web/app/lib/credential-heuristics.ts
new file mode 100644
index 000000000..a50fef3c1
--- /dev/null
+++ b/apps/fabro-web/app/lib/credential-heuristics.ts
@@ -0,0 +1,32 @@
+const TEMPLATE_REFERENCE_PATTERN = /\{\{\s*(secrets|env|vars)\./i;
+const CREDENTIAL_KEY_PATTERN = /authorization|password|passwd|secret|token|api[-_]?key|_(key|token|secret)$/i;
+
+// True when a key/value pair looks credential-bearing and should be nudged
+// toward a secret. Never flags an already-templated value.
+export function looksLikeCredential(key: string, value: string): boolean {
+  if (value === "" || TEMPLATE_REFERENCE_PATTERN.test(value)) return false;
+  if (CREDENTIAL_KEY_PATTERN.test(key)) return true;
+  return looksHighEntropy(value);
+}
+
+function looksHighEntropy(value: string): boolean {
+  if (value.length < 20 || /\s/.test(value)) return false;
+  const classes = [/[a-z]/.test(value), /[A-Z]/.test(value), /\d/.test(value)]
+    .filter(Boolean).length;
+  return classes >= 2;
+}
+
+// Suggest a secret name derived from the key (UPPER_SNAKE_CASE, alnum + _).
+export function secretNameForKey(key: string): string {
+  const name = key
+    .toUpperCase()
+    .replace(/[^A-Z0-9]+/g, "_")
+    .replace(/_+/g, "_")
+    .replace(/^_+|_+$/g, "");
+  return name || "SECRET";
+}
+
+// The interpolation reference to store in place of a literal secret value.
+export function secretReference(name: string): string {
+  return `{{ secrets.${name} }}`;
+}
